<x-filament-panels::page><div wire:poll.5s>@php($s=$this->stats)<style>.ip{display:flex;flex-direction:column;gap:18px}.ip-hero,.ip-panel,.ip-stat{border:1px solid rgba(124,58,237,.18);border-radius:18px;background:#fff}.ip-hero{padding:22px;background:linear-gradient(125deg,#fff,#f5f3ff,#ede9fe)}.ip-title{font-size:27px;font-weight:950;color:#111827}.ip-sub{color:#6b7280;font-size:12px}.ip-select{margin-top:15px;width:320px;border:1px solid #ddd6fe;border-radius:11px;padding:10px}.ip-stats{display:grid;grid-template-columns:repeat(6,1fr);gap:10px}.ip-stat{padding:15px}.ip-stat span{font-size:9px;font-weight:900;color:#7c3aed;text-transform:uppercase}.ip-stat b{display:block;font-size:22px;color:#111827}.ip-row{padding:17px;border-bottom:1px solid #eee}.ip-head{display:flex;justify-content:space-between;gap:12px}.ip-name{font-weight:900;color:#111827}.ip-meta{font-size:10px;color:#6b7280;margin-top:5px}.ip-progress{height:8px;border-radius:99px;background:#e5e7eb;overflow:hidden;margin-top:12px}.ip-progress i{display:block;height:100%;background:linear-gradient(90deg,#7c3aed,#a855f7)}.ip-counts{display:flex;gap:14px;margin-top:8px;font-size:10px;color:#6b7280}.ip-btn{border:0;border-radius:9px;padding:7px 10px;background:#ede9fe;color:#5b21b6;font-weight:800;font-size:10px}html.dark .ip-hero,html.dark .ip-panel,html.dark .ip-stat{background:linear-gradient(145deg,#09080e,#171023);border-color:rgba(167,139,250,.24)}html.dark .ip-title,html.dark .ip-name,html.dark .ip-stat b{color:#f8fafc}html.dark .ip-select{background:#100d17;color:#fff;color-scheme:dark}@media(max-width:900px){.ip-stats{grid-template-columns:repeat(3,1fr)}}</style><div class="ip"><section class="ip-hero"><div class="ip-title">📥 Voter Import Progress</div><div class="ip-sub">Live row progress, imported/skipped counts, failure details and safe retry.</div><select class="ip-select" wire:model.live="constituencyId"><option value="">All Assemblies</option>@foreach($this->constituencies as $c)<option value="{{$c->id}}">{{$c->name}}</option>@endforeach</select></section><div class="ip-stats">@foreach(['total'=>'Imports','running'=>'Running','completed'=>'Completed','failed'=>'Failed','imported'=>'Voters Imported','skipped'=>'Rows Skipped'] as $k=>$l)<div class="ip-stat"><span>{{$l}}</span><b>{{number_format($s[$k])}}</b></div>@endforeach</div><section class="ip-panel">@forelse($this->batches as $b)<div class="ip-row"><div class="ip-head"><div><div class="ip-name">{{$b->file_name}}</div><div class="ip-meta">{{$b->constituency?->name}} · {{$b->status}} · {{$b->created_at->format('d M Y, h:i A')}}</div></div><div>@if($b->status==='Failed')<button class="ip-btn" wire:click="retryImport({{$b->id}})">Retry</button>@endif @if(count($b->errors??[]))<button class="ip-btn" wire:click="downloadErrors({{$b->id}})">Error CSV</button>@endif</div></div><div class="ip-progress"><i style="width:{{$b->progress_percent}}%"></i></div><div class="ip-counts"><span>{{$b->progress_percent}}%</span><span>Processed: {{number_format($b->processed_rows)}} / {{number_format($b->total_rows)}}</span><span>Imported: {{number_format($b->imported_rows)}}</span><span>Skipped: {{number_format($b->skipped_rows)}}</span></div>@if($b->failure_message)<div class="ip-meta" style="color:#dc2626">{{$b->failure_message}}</div>@endif</div>@empty<div class="ip-row">No tracked voter imports yet. New imports will appear automatically.</div>@endforelse</section></div></div></x-filament-panels::page>
